        setAssessment(data)
        setResults(calculateResults(data))
    }, [])

    // ← ADD THIS RIGHT HERE
    useEffect(() => {
        if (window.location.hash === '#coach') {
            setActiveTab('coach')
        }
    }, [])

    const sendMessage = async () => {
        if (!input.trim() || loading) return
        const userMsg = input.trim()
        setInput('')
        setMessages(m => [...m, { role: 'user', text: userMsg }])
        setLoading(true)
        try {
            const res = await fetch('/api/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    message: userMsg,
                    context: {
                        topCareer: results[0]?.career,
                        score: results[0]?.score,
                        skills: assessment?.skills || [],
                    }
                })
            })
            const data = await res.json()
            setMessages(m => [...m, { role: 'ai', text: data.reply }])
        } catch {
            setMessages(m => [...m, { role: 'ai', text: 'Sorry, something went wrong. Please try again.' }])
        }
        setLoading(false)
    }

    if (!results.length) return (
        <div style={{ minHeight: '100vh', background: '#070b16', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <p style={{ color: '#94a3b8' }}>Loading results...</p>
        </div>
    )

    const top = results[0]
    const radarData = assessment?.aptitude
        ? Object.entries(assessment.aptitude).map(([k, v]) => ({ dim: k, value: v }))
        : []
    const barData = results.map(r => ({ career: r.career.split(' ')[0], score: r.score }))

    const tabs = ['overview', 'careers', 'coach']

    return (
        <div style={{ minHeight: '100vh', background: '#070b16', paddingTop: '80px', padding: '80px 24px 48px' }}>
            <div style={{ maxWidth: '1100px', margin: '0 auto' }}>

                {/* Header */}
                <div style={{ marginBottom: '32px' }}>
                    <h1 style={{ fontFamily: 'Syne, sans-serif', fontSize: '36px', fontWeight: 800, color: 'white', marginBottom: '8px' }}>
                        Your Career Profile
                    </h1>
                    <p style={{ color: '#94a3b8' }}>Based on your assessment results</p>
                </div>

                {/* Stat Cards */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '16px', marginBottom: '32px' }}>
                    {[
                        { label: 'Top Career Match', value: top.career, color: '#3b82f6' },
                        { label: 'Compatibility Score', value: `${top.score}%`, color: '#22c55e' },
                        { label: 'Skills Identified', value: assessment?.skills?.length || 0, color: '#a855f7' },
                    ].map(card => (
                        <div key={card.label} style={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '16px', padding: '24px' }}>
                            <p style={{ color: '#64748b', fontSize: '13px', marginBottom: '8px' }}>{card.label}</p>
                            <p style={{ fontFamily: 'Syne, sans-serif', fontSize: '24px', fontWeight: 800, color: card.color }}>{card.value}</p>
                        </div>
                    ))}
                </div>

                {/* Tabs */}
                <div style={{ display: 'flex', gap: '8px', marginBottom: '24px' }}>
                    {tabs.map(tab => (
                        <button key={tab} onClick={() => setActiveTab(tab)} style={{
                            padding: '8px 20px', borderRadius: '999px', border: 'none', cursor: 'pointer', fontWeight: 600, fontSize: '14px',
                            background: activeTab === tab ? '#3b82f6' : 'rgba(255,255,255,0.05)',
                            color: activeTab === tab ? 'white' : '#94a3b8',
                            transition: 'all 0.2s',
                        }}>
                            {tab === 'overview' ? '📊 Overview' : tab === 'careers' ? '🎯 Careers' : '🤖 AI Coach'}
                        </button>
                    ))}
                </div>

                {/* Overview Tab */}
                {activeTab === 'overview' && (
                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                        {/* Bar Chart */}
                        <div style={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '16px', padding: '24px' }}>
                            <h3 style={{ color: 'white', fontWeight: 700, marginBottom: '20px' }}>🎯 Career Compatibility</h3>
                            <ResponsiveContainer width="100%" height={220}>
                                <BarChart data={barData}>
                                    <XAxis dataKey="career" tick={{ fill: '#64748b', fontSize: 11 }} />
                                    <YAxis tick={{ fill: '#64748b', fontSize: 11 }} />
                                    <Tooltip contentStyle={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', color: 'white' }} />
                                    <Bar dataKey="score" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                                </BarChart>
                            </ResponsiveContainer>
                        </div>

                        {/* Radar Chart */}
                        <div style={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '16px', padding: '24px' }}>
                            <h3 style={{ color: 'white', fontWeight: 700, marginBottom: '20px' }}>🧠 Aptitude Profile</h3>
                            <ResponsiveContainer width="100%" height={220}>
                                <RadarChart data={radarData}>
                                    <PolarGrid stroke="rgba(255,255,255,0.1)" />
                                    <PolarAngleAxis dataKey="dim" tick={{ fill: '#64748b', fontSize: 10 }} />
                                    <PolarRadiusAxis domain={[0, 100]} tick={false} axisLine={false} />
                                    <Radar dataKey="value" stroke="#a855f7" fill="#a855f7" fillOpacity={0.3} />
                                </RadarChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                )}

                {/* Careers Tab */}
                {activeTab === 'careers' && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                        {results.map((r, i) => (
                            <div key={r.career} style={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '16px', padding: '24px' }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                                    <div>
                                        <h3 style={{ color: 'white', fontWeight: 700, fontSize: '18px' }}>{r.career}</h3>
                                        <p style={{ color: '#64748b', fontSize: '13px' }}>{r.skillMatches.length} / {CAREER_PROFILES[r.career].skills.length} skills match</p>
                                    </div>
                                    <span style={{ fontFamily: 'Syne, sans-serif', fontSize: '28px', fontWeight: 800, color: i === 0 ? '#22c55e' : '#3b82f6' }}>
                                        {r.score}%
                                    </span>
                                </div>
                                {/* Progress bar */}
                                <div style={{ height: '6px', background: 'rgba(255,255,255,0.08)', borderRadius: '999px', marginBottom: '12px' }}>
                                    <div style={{ height: '100%', width: `${r.score}%`, background: i === 0 ? '#22c55e' : '#3b82f6', borderRadius: '999px', transition: 'width 1s ease' }} />
                                </div>
                                {/* Missing skills */}
                                {r.missingSkills.length > 0 && (
                                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '6px' }}>
                                        {r.missingSkills.map(s => (
                                            <span key={s} style={{ background: 'rgba(239,68,68,0.1)', color: '#f87171', border: '1px solid rgba(239,68,68,0.2)', borderRadius: '999px', padding: '3px 10px', fontSize: '12px' }}>
                                                missing: {s}
                                            </span>
                                        ))}
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                )}

                {/* AI Coach Tab */}
                {activeTab === 'coach' && (
                    <div style={{ background: '#0d1526', border: '1px solid rgba(255,255,255,0.06)', borderRadius: '16px', overflow: 'hidden' }}>
                        <div style={{ padding: '24px', borderBottom: '1px solid rgba(255,255,255,0.06)' }}>
                            <h3 style={{ color: 'white', fontWeight: 700 }}>🤖 AI Career Coach</h3>
                            <p style={{ color: '#64748b', fontSize: '13px' }}>Powered by GPT-4o — ask anything about your career path</p>
                        </div>

                        {/* Messages */}
                        <div style={{ height: '380px', overflowY: 'auto', padding: '24px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
                            {messages.length === 0 && (
                                <div style={{ textAlign: 'center', margin: 'auto' }}>
                                    <div style={{ fontSize: '40px', marginBottom: '12px' }}>💬</div>
                                    <p style={{ color: '#64748b' }}>Ask me anything about your career path!</p>
                                    {['How do I become a {top.career}?', 'What skills should I learn first?', 'How long to reach my goal?'].map(q => (
                                        <button key={q} onClick={() => setInput(q.replace('{top.career}', top.career))}
                                            style={{ display: 'block', margin: '8px auto', background: 'rgba(59,130,246,0.1)', color: '#60a5fa', border: '1px solid rgba(59,130,246,0.2)', borderRadius: '999px', padding: '8px 16px', cursor: 'pointer', fontSize: '13px' }}>
                                            {q.replace('{top.career}', top.career)}
                                        </button>
                                    ))}
                                </div>
                            )}
                            {messages.map((m, i) => (
                                <div key={i} style={{ display: 'flex', justifyContent: m.role === 'user' ? 'flex-end' : 'flex-start' }}>
                                    <div style={{
                                        maxWidth: '80%', padding: '12px 16px', borderRadius: '16px', fontSize: '14px', lineHeight: 1.6,
                                        background: m.role === 'user' ? '#3b82f6' : 'rgba(255,255,255,0.05)',
                                        color: 'white',
                                    }}>
                                        {m.text}
                                    </div>
                                </div>
                            ))}
                            {loading && (
                                <div style={{ display: 'flex', gap: '6px', padding: '12px 16px' }}>
                                    {[0, 1, 2].map(i => (
                                        <div key={i} style={{ width: '8px', height: '8px', borderRadius: '50%', background: '#3b82f6', animation: `bounce 0.6s ${i * 0.1}s infinite alternate` }} />
                                    ))}
                                </div>
                            )}
                        </div>

                        {/* Input */}
                        <div style={{ padding: '16px 24px', borderTop: '1px solid rgba(255,255,255,0.06)', display: 'flex', gap: '12px' }}>
                            <input
                                value={input}
                                onChange={e => setInput(e.target.value)}
                                onKeyDown={e => e.key === 'Enter' && sendMessage()}
                                placeholder="Ask about your career path..."
                                style={{ flex: 1, background: 'rgba(255,255,255,0.05)', color: 'white', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '10px', padding: '12px 16px', fontSize: '14px', outline: 'none' }}
                            />
                            <button onClick={sendMessage} style={{ background: '#3b82f6', color: 'white', border: 'none', borderRadius: '10px', padding: '12px 20px', fontWeight: 700, cursor: 'pointer' }}>
                                Send
                            </button>
                        </div>
                    </div>
                )}
            </div>
        </div>
    )
}

'use client';

import { useState } from 'react';
import { useSession, signOut } from 'next-auth/react';
import Image from 'next/image';

const NAV_LINKS = [
    { label: 'Features', href: '#features' },
    { label: 'AI Coach', href: '/results#coach' },
    { label: 'Resume', href: '/resume' },
    { label: 'Assessment', href: '/assessment' },
];

export default function Navbar() {
    const { data: session, status } = useSession();
    const [hovered, setHovered] = useState(null);
    const [menuOpen, setMenuOpen] = useState(false);

    const isLoading = status === 'loading';
    const isLoggedIn = !!session?.user;

    return (
        <header
            style={{
                position: 'fixed',
                top: 0,
                left: 0,
                right: 0,
                zIndex: 100,
                background: 'rgba(7, 11, 22, 0.88)',
                backdropFilter: 'blur(16px)',
                WebkitBackdropFilter: 'blur(16px)',
                borderBottom: '1px solid var(--color-border-muted)',
            }}
        >
            <div
                className="container"
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    height: '64px',
                }}
            >
                {/* ── Logo ─────────────────────────────────────── */}
                <a
                    href="/"
                    style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: '0.5rem',
                        textDecoration: 'none',
                    }}
                >
                    <span style={{ fontSize: '1.375rem' }}>⚡</span>
                    <span
                        style={{
                            fontFamily: 'var(--font-display)',
                            fontWeight: 700,
                            fontSize: '1.1875rem',
                            letterSpacing: '-0.02em',
                            background: 'linear-gradient(135deg, #f1f5f9, #94a3b8)',
                            WebkitBackgroundClip: 'text',
                            WebkitTextFillColor: 'transparent',
                            backgroundClip: 'text',
                        }}
                    >
                        Skill Gap
                    </span>
                </a>

                {/* ── Nav Links (desktop) ───────────────────────── */}
                <nav
                    className="hide-mobile"
                    style={{ display: 'flex', alignItems: 'center', gap: '2rem' }}
                >
                    {NAV_LINKS.map((item) => (
                        <a
                            key={item.label}
                            href={item.href}
                            onMouseEnter={() => setHovered(item.label)}
                            onMouseLeave={() => setHovered(null)}
                            style={{
                                fontFamily: 'var(--font-body)',
                                fontSize: '0.9rem',
                                fontWeight: 500,
                                color: hovered === item.label ? 'var(--text-primary)' : 'var(--text-muted)',
                                textDecoration: 'none',
                                transition: 'color 150ms ease',
                            }}
                        >
                            {item.label}
                        </a>
                    ))}
                </nav>

                {/* ── Auth Area ─────────────────────────────────── */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                    {isLoading ? (
                        /* Skeleton placeholder while session loads */
                        <div
                            className="skeleton"
                            style={{ width: '100px', height: '34px', borderRadius: '9999px' }}
                        />
                    ) : isLoggedIn ? (
                        /* Logged-in: avatar + name + dropdown */
                        <div style={{ position: 'relative' }}>
                            <button
                                onClick={() => setMenuOpen((o) => !o)}
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '0.5rem',
                                    background: 'var(--color-card)',
                                    border: '1px solid var(--color-border)',
                                    borderRadius: '9999px',
                                    padding: '0.25rem 0.75rem 0.25rem 0.25rem',
                                    cursor: 'pointer',
                                    transition: 'border-color 150ms',
                                }}
                                onMouseEnter={(e) => (e.currentTarget.style.borderColor = 'var(--color-blue)')}
                                onMouseLeave={(e) => (e.currentTarget.style.borderColor = 'var(--color-border)')}
                            >
                                {/* Avatar */}
                                {session.user.image ? (
                                    <Image
                                        src={session.user.image}
                                        alt={session.user.name ?? 'User'}
                                        width={28}
                                        height={28}
                                        style={{ borderRadius: '50%', flexShrink: 0 }}
                                    />
                                ) : (
                                    <div
                                        style={{
                                            width: '28px',
                                            height: '28px',
                                            borderRadius: '50%',
                                            background: 'var(--color-blue)',
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            fontSize: '0.75rem',
                                            fontWeight: 700,
                                            color: '#fff',
                                            flexShrink: 0,
                                        }}
                                    >
                                        {(session.user.name ?? 'U')[0].toUpperCase()}
                                    </div>
                                )}
                                {/* Name */}
                                <span
                                    className="hide-mobile"
                                    style={{
                                        fontFamily: 'var(--font-body)',
                                        fontSize: '0.875rem',
                                        fontWeight: 500,
                                        color: 'var(--text-primary)',
                                        maxWidth: '120px',
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis',
                                        whiteSpace: 'nowrap',
                                    }}
                                >
                                    {session.user.name?.split(' ')[0]}
                                </span>
                                {/* Chevron */}
                                <svg
                                    width="12"
                                    height="12"
                                    viewBox="0 0 12 12"
                                    fill="none"
                                    style={{
                                        transform: menuOpen ? 'rotate(180deg)' : 'rotate(0deg)',
                                        transition: 'transform 200ms ease',
                                        flexShrink: 0,
                                    }}
                                >
                                    <path d="M2 4l4 4 4-4" stroke="var(--text-muted)" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
                                </svg>
                            </button>

                            {/* Dropdown */}
                            {menuOpen && (
                                <div
                                    style={{
                                        position: 'absolute',
                                        top: 'calc(100% + 8px)',
                                        right: 0,
                                        minWidth: '180px',
                                        background: 'var(--color-card)',
                                        border: '1px solid var(--color-border)',
                                        borderRadius: 'var(--radius-lg)',
                                        boxShadow: 'var(--shadow-lg)',
                                        overflow: 'hidden',
                                        animation: 'scaleIn 0.15s ease both',
                                        transformOrigin: 'top right',
                                    }}
                                >
                                    {[
                                        { label: '📊 Dashboard', href: '/dashboard' },
                                        { label: '🎯 Assess Skills', href: '/assessment' },
                                        { label: '📄 Resume', href: '/resume' },
                                    ].map((item) => (
                                        <a
                                            key={item.label}
                                            href={item.href}
                                            style={{
                                                display: 'block',
                                                padding: '0.6875rem 1rem',
                                                fontSize: '0.875rem',
                                                color: 'var(--text-secondary)',
                                                textDecoration: 'none',
                                                transition: 'background 100ms, color 100ms',
                                                borderBottom: '1px solid var(--color-border-muted)',
                                            }}
                                            onMouseEnter={(e) => {
                                                e.currentTarget.style.background = 'var(--color-blue-glow)';
                                                e.currentTarget.style.color = 'var(--text-primary)';
                                            }}
                                            onMouseLeave={(e) => {
                                                e.currentTarget.style.background = 'transparent';
                                                e.currentTarget.style.color = 'var(--text-secondary)';
                                            }}
                                        >
                                            {item.label}
                                        </a>
                                    ))}

                                    {/* Sign out */}
                                    <button
                                        onClick={() => signOut({ callbackUrl: '/' })}
                                        style={{
                                            display: 'block',
                                            width: '100%',
                                            padding: '0.6875rem 1rem',
                                            fontSize: '0.875rem',
                                            color: 'var(--color-red-light)',
                                            textAlign: 'left',
                                            background: 'transparent',
                                            border: 'none',
                                            cursor: 'pointer',
                                            transition: 'background 100ms',
                                        }}
                                        onMouseEnter={(e) => (e.currentTarget.style.background = 'var(--color-red-glow)')}
                                        onMouseLeave={(e) => (e.currentTarget.style.background = 'transparent')}
                                    >
                                        🚪 Sign Out
                                    </button>
                                </div>
                            )}
                        </div>
                    ) : (
                        /* Not logged in: Sign In button */
                        <a href="/login" className="btn btn-primary btn-sm">
                            Sign In
                        </a>
                    )}
                </div>
            </div>
        </header >
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { ChevronRight, ChevronLeft, Plus, X, CheckCircle2 } from "lucide-react";

export default function AssessmentPage() {
    const router = useRouter();
    const [step, setStep] = useState(1);
    const totalSteps = 3;

    // State Step 1
    const [cgpa, setCgpa] = useState(3.0);
    const [education, setEducation] = useState("Bachelor's");

    // State Step 2
    const [currentSkill, setCurrentSkill] = useState("");
    const [skills, setSkills] = useState([]);
    const quickSkills = [
        "python", "javascript", "react", "sql", "java",
        "figma", "docker", "aws", "communication", "leadership"
    ];

    // State Step 3
    const [aptitudes, setAptitudes] = useState({
        Logical: 50,
        Analytical: 50,
        Technical: 50,
        Creative: 50,
        Communication: 50,
        Leadership: 50,
        Mathematical: 50
    });

    const handleAddSkill = (skill) => {
        const s = skill.trim().toLowerCase();
        if (s && !skills.includes(s)) {
            setSkills([...skills, s]);
        }
        setCurrentSkill("");
    };

    const handleRemoveSkill = (skillToRemove) => {
        setSkills(skills.filter(s => s !== skillToRemove));
    };

    const handleComplete = () => {
        const assessmentData = {
            academic: {
                cgpa: parseFloat(cgpa),
                education
            },
            skills,
            aptitudes
        };
        localStorage.setItem("skillgap-assessment", JSON.stringify(assessmentData));
        router.push("/results");
    };

    return (
        <div className="min-h-screen bg-[#070b16] text-white p-6 flex flex-col items-center">
            <div className="w-full max-w-3xl mt-12">
                {/* Progress Header */}
                <div className="mb-8">
                    <div className="flex justify-between items-end mb-4">
                        <h1 className="text-3xl font-bold font-syne">Assessment</h1>
                        <span className="text-sm text-gray-400 font-dm-sans">
                            Step {step} of {totalSteps}
                        </span>
                    </div>
                    <div className="w-full bg-[#0d1526] h-2 rounded-full overflow-hidden">
                        <div
                            className="h-full bg-blue-500 transition-all duration-500 ease-out"
                            style={{ width: `${(step / totalSteps) * 100}%` }}
                        ></div>
                    </div>
                </div>

                {/* Form Container */}
                <div className="bg-[#0d1526] rounded-2xl p-8 shadow-xl border border-white/5">
                    {step === 1 && (
                        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                            <h2 className="text-2xl font-semibold mb-6">Academic Background</h2>

                            <div className="space-y-4">
                                <div className="flex justify-between items-center">
                                    <label className="text-gray-300">CGPA (0.0 - 4.0)</label>
                                    <span className="text-blue-500 font-bold text-xl">{cgpa.toFixed(1)}</span>
                                </div>
                                <input
                                    type="range"
                                    min="0.0"
                                    max="4.0"
                                    step="0.1"
                                    value={cgpa}
                                    onChange={(e) => setCgpa(parseFloat(e.target.value))}
                                    className="w-full accent-blue-500 h-2 bg-[#070b16] rounded-lg appearance-none cursor-pointer"
                                />
                            </div>

                            <div className="space-y-4">
                                <label className="text-gray-300 block">Education Level</label>
                                <select
                                    value={education}
                                    onChange={(e) => setEducation(e.target.value)}
                                    className="w-full bg-[#070b16] border border-white/10 rounded-xl p-4 text-white focus:outline-none focus:border-blue-500 transition-colors cursor-pointer appearance-none"
                                >
                                    <option value="High School">High School</option>
                                    <option value="Bachelor's">Bachelor's Degree</option>
                                    <option value="Master's">Master's Degree</option>
                                    <option value="PhD">PhD</option>
                                </select>
                            </div>

                            <div className="pt-6 flex justify-end">
                                <button
                                    onClick={() => setStep(2)}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-medium transition-colors flex items-center gap-2"
                                >
                                    Next Step <ChevronRight className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    )}

                    {step === 2 && (
                        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                            <h2 className="text-2xl font-semibold mb-6">Your Skills</h2>

                            <div className="space-y-4">
                                <label className="text-gray-300 block">Add technical & soft skills</label>
                                <div className="flex gap-3">
                                    <input
                                        type="text"
                                        value={currentSkill}
                                        onChange={(e) => setCurrentSkill(e.target.value)}
                                        onKeyDown={(e) => e.key === 'Enter' && handleAddSkill(currentSkill)}
                                        placeholder="e.g. React, Docker..."
                                        className="flex-1 bg-[#070b16] border border-white/10 rounded-xl p-4 text-white focus:outline-none focus:border-blue-500 transition-colors"
                                    />
                                    <button
                                        onClick={() => handleAddSkill(currentSkill)}
                                        className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-4 rounded-xl font-medium transition-colors flex items-center gap-2"
                                    >
                                        <Plus className="w-5 h-5" /> Add
                                    </button>
                                </div>
                            </div>

                            {skills.length > 0 && (
                                <div className="flex flex-wrap gap-2 pt-2">
                                    {skills.map(skill => (
                                        <div key={skill} className="bg-blue-500/10 text-blue-400 border border-blue-500/20 px-4 py-2 rounded-full flex items-center gap-2">
                                            <span className="text-sm font-medium">{skill}</span>
                                            <button onClick={() => handleRemoveSkill(skill)} className="hover:text-blue-300 transition-colors">
                                                <X className="w-4 h-4" />
                                            </button>
                                        </div>
                                    ))}
                                </div>
                            )}

                            <div className="space-y-3 pt-4 border-t border-white/5">
                                <label className="text-sm text-gray-500 block">Quick Add:</label>
                                <div className="flex flex-wrap gap-2">
                                    {quickSkills.map(skill => (
                                        <button
                                            key={skill}
                                            onClick={() => handleAddSkill(skill)}
                                            disabled={skills.includes(skill)}
                                            className="bg-[#070b16] border border-white/5 hover:border-white/20 disabled:opacity-30 disabled:hover:border-white/5 text-gray-400 px-3 py-1.5 rounded-lg text-sm transition-colors"
                                        >
                                            {skill}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="pt-6 flex justify-between">
                                <button
                                    onClick={() => setStep(1)}
                                    className="bg-transparent border border-white/10 hover:bg-white/5 text-white px-6 py-3 rounded-xl font-medium transition-colors flex items-center gap-2"
                                >
                                    <ChevronLeft className="w-5 h-5" /> Previous
                                </button>
                                <button
                                    onClick={() => setStep(3)}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-medium transition-colors flex items-center gap-2"
                                >
                                    Next Step <ChevronRight className="w-5 h-5" />
                                </button>
                            </div>
                        </div>
                    )}

                    {step === 3 && (
                        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                            <h2 className="text-2xl font-semibold mb-6">Aptitude Rating</h2>
                            <p className="text-gray-400 text-sm mb-6">Rate your proficiency in the following areas from 0 to 100.</p>

                            <div className="space-y-6">
                                {Object.keys(aptitudes).map(trait => (
                                    <div key={trait} className="space-y-2">
                                        <div className="flex justify-between items-center">
                                            <label className="text-gray-300 text-sm font-medium">{trait}</label>
                                            <span className="text-blue-500 font-bold text-sm bg-blue-500/10 px-2 py-1 rounded-md min-w-[3rem] text-center">
                                                {aptitudes[trait]}
                                            </span>
                                        </div>
                                        <input
                                            type="range"
                                            min="0"
                                            max="100"
                                            step="1"
                                            value={aptitudes[trait]}
                                            onChange={(e) => setAptitudes({ ...aptitudes, [trait]: parseInt(e.target.value) })}
                                            className="w-full accent-blue-500 h-1.5 bg-[#070b16] rounded-lg appearance-none cursor-pointer"
                                        />
                                    </div>
                                ))}
                            </div>

                            <div className="pt-8 flex justify-between border-t border-white/5">
                                <button
                                    onClick={() => setStep(2)}
                                    className="bg-transparent border border-white/10 hover:bg-white/5 text-white px-6 py-3 rounded-xl font-medium transition-colors flex items-center gap-2"
                                >
                                    <ChevronLeft className="w-5 h-5" /> Previous
                                </button>
                                <button
                                    onClick={handleComplete}
                                    className="bg-blue-600 hover:bg-blue-700 text-white px-8 py-3 rounded-xl font-medium transition-colors flex items-center gap-2 shadow-lg shadow-blue-500/20"
                                >
                                    <CheckCircle2 className="w-5 h-5" /> Complete Assessment
                                </button>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}

'use client'
import { useSession } from 'next-auth/react'
import { useRouter } from 'next/navigation'
import { useEffect } from 'react'

export default function DashboardPage() {
    const { data: session, status } = useSession()
    const router = useRouter()

    useEffect(() => {
        if (status === 'unauthenticated') {
            router.push('/login')
        }
    }, [status, router])

    if (status === 'loading') {
        return (
            <div style={{
                minHeight: '100vh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                background: '#070b16',
            }}>
                <p style={{ color: '#94a3b8' }}>Loading...</p>
            </div>
        )
    }

    return (
        <div style={{
            minHeight: '100vh',
            background: '#070b16',
            paddingTop: '80px',
            padding: '80px 32px 48px',
            maxWidth: '1100px',
            margin: '0 auto',
        }}>
            {/* Welcome */}
            <div style={{ marginBottom: '40px' }}>
                <h1 style={{
                    fontFamily: 'Syne, sans-serif',
                    fontSize: '36px',
                    fontWeight: 800,
                    color: 'white',
                    marginBottom: '8px',
                }}>
                    Welcome back, {session?.user?.name?.split(' ')[0]}! 👋
                </h1>
                <p style={{ color: '#94a3b8', fontSize: '16px' }}>
                    Ready to discover your perfect career path?
                </p>
            </div>

            {/* Quick Action Cards */}
            <div style={{
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
                gap: '16px',
                marginBottom: '48px',
            }}>
                {[
                    {
                        icon: '🎯',
                        title: 'Start Assessment',
                        desc: 'Discover your career compatibility score',
                        href: '/assessment',
                        color: '#3b82f6',
                    },
                    {
                        icon: '📄',
                        title: 'Resume Analyzer',
                        desc: 'Get your ATS score and improvements',
                        href: '/resume',
                        color: '#22c55e',
                        badge: 'NEW',
                    },
                    {
                        icon: '🤖',
                        title: 'AI Career Coach',
                        desc: 'Chat with your personal AI coach',
                        href: '/results',
                        color: '#a855f7',
                    },
                ].map((card) => (
                    <div
                        key={card.title}
                        onClick={() => router.push(card.href)}
                        style={{
                            background: '#0d1526',
                            border: '1px solid rgba(255,255,255,0.06)',
                            borderRadius: '12px',
                            padding: '24px',
                            cursor: 'pointer',
                            transition: 'all 0.2s',
                        }}
                        onMouseEnter={e => {
                            e.currentTarget.style.borderColor = card.color + '40'
                            e.currentTarget.style.transform = 'translateY(-2px)'
                        }}
                        onMouseLeave={e => {
                            e.currentTarget.style.borderColor = 'rgba(255,255,255,0.06)'
                            e.currentTarget.style.transform = 'translateY(0)'
                        }}
                    >
                        <div style={{ fontSize: '32px', marginBottom: '12px' }}>
                            {card.icon}
                        </div>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            marginBottom: '6px',
                        }}>
                            <h3 style={{
                                fontSize: '16px',
                                fontWeight: 700,
                                color: 'white',
                            }}>
                                {card.title}
                            </h3>
                            {card.badge && (
                                <span style={{
                                    fontSize: '10px',
                                    padding: '2px 8px',
                                    borderRadius: '999px',
                                    background: 'rgba(59,130,246,0.2)',
                                    color: '#60a5fa',
                                    fontWeight: 600,
                                }}>
                                    {card.badge}
                                </span>
                            )}
                        </div>
                        <p style={{ color: '#94a3b8', fontSize: '13px' }}>
                            {card.desc}
                        </p>
                    </div>
                ))}
            </div>

            {/* User Info Card */}
            <div style={{
                background: '#0d1526',
                border: '1px solid rgba(255,255,255,0.06)',
                borderRadius: '12px',
                padding: '24px',
                display: 'flex',
                alignItems: 'center',
                gap: '16px',
            }}>
                {session?.user?.image && (
                    <img
                        src={session.user.image}
                        alt="avatar"
                        style={{
                            width: '48px',
                            height: '48px',
                            borderRadius: '50%',
                        }}
                    />
                )}
                <div>
                    <p style={{ fontWeight: 700, color: 'white' }}>
                        {session?.user?.name}
                    </p>
                    <p style={{ color: '#94a3b8', fontSize: '13px' }}>
                        {session?.user?.email}
                    </p>
                </div>
                <div style={{ marginLeft: 'auto' }}>
                    <span style={{
                        padding: '4px 12px',
                        borderRadius: '999px',
                        background: 'rgba(34,197,94,0.15)',
                        color: '#22c55e',
                        fontSize: '12px',
                        fontWeight: 600,
                        border: '1px solid rgba(34,197,94,0.3)',
                    }}>
                        ✓ Logged In
                    </span>
                </div>
            </div>
        </div>
    )
}
